/**
 * Prompt Registry — tool-local actions.
 *
 * Category: AI / LLM PM (squad S12a, Wave 3 — CRUD-backed tools)
 * Tool:     Versioned prompt catalog (draft → review → production → deprecated)
 *
 * Agent surface: tool.prompt_registry.*
 * Backing CRUD : workspace.prompt.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts)
 *
 * ─── CRUD-BACKED tool pattern (vs the calculator pattern) ────────────
 * Prompts are record-keeping entities: generic create / list / update /
 * delete already exist via the auto-generated workspace.prompt.* surface.
 * This file only adds VERBS THE AGENT WANTS TO SPEAK in the prompt
 * lifecycle's domain vocabulary:
 *
 *   1. list_state               — read all prompt versions, grouped by
 *                                 `name`, with the production + latest-draft
 *                                 pointers and a byStatus / totals summary.
 *                                 Lets the agent plan ("what's deployed?
 *                                 how many drafts pending review?") without
 *                                 paging through every individual version.
 *   2. get_production_prompt    — read: resolve {name} → the version
 *                                 currently in production. Useful for any
 *                                 downstream agent that wants to USE the
 *                                 currently-deployed prompt body without
 *                                 hard-coding a specific version id.
 *   3. promote_to_production    — write: set status="production" AND
 *                                 auto-demote any OTHER version of the
 *                                 same `name` from production to
 *                                 deprecated. Enforces the
 *                                 single-production-per-name invariant,
 *                                 the same rule the in-app Publish button
 *                                 and status menu apply. requiresConfirmation:true
 *                                 (default for `write`) — this is a real
 *                                 production cut-over.
 *   4. deprecate                — write: set status="deprecated", append
 *                                 reason to changeNote if provided.
 *                                 Idempotent — repeated calls are no-ops
 *                                 once the version is already deprecated.
 *   5. record_eval              — write: set evalScore on a version.
 *                                 Surface designed for an LLM-eval agent
 *                                 to write back results without having
 *                                 to read-merge-write the whole row.
 *                                 requiresConfirmation:false — overwriting
 *                                 a score is non-destructive (the previous
 *                                 score wasn't load-bearing for anything
 *                                 except this metric).
 *
 * ─── PRODUCTION INVARIANT ────────────────────────────────────────────
 * At most one production version per `name`. `promote_to_production`
 * enforces this by demoting any existing production version of the same
 * name to `deprecated` before setting the target to `production`. The
 * in-app Publish button and status menu do the same (`promote` in
 * prompt-registry-client.tsx); keep the two in step. Older data can still
 * hold TWO production versions of one name (the UI used to allow it:
 * publish v1.4.0, then v1.5.0 without deprecating v1.4.0), so
 * `get_production_prompt` stays defensive against that legacy state — it
 * picks the row with the latest `publishedAt` as a deterministic
 * tiebreaker.
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.prompt_registry` (snake_case to round-trip cleanly
 * through Anthropic's tool-name munging). The user-facing tool route is
 * `/prompt-registry` (kebab-case), but kebab is illegal in tool ids —
 * `prompt_registry` is the canonical action-namespace form.
 *
 * Entity kind for server-store is `workspace:prompt` (single-word
 * entity, no asymmetry between the kindFromToolId mapping and the
 * browser-side `registerCollection("prompt", "prompts")` registration).
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import {
  serverListEntities,
  serverGetEntity,
  serverUpsertEntity,
  serverBulkUpsertEntities,
} from "../server-store";
import type { PromptVersion } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.prompt")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface.
 *  Browser-side sync registers as "workspace:prompt" (registerCollection
 *  in workspace-store.ts) — no DACI-style asymmetry here because the
 *  entity name is a single word. */
const KIND_PROMPT = "workspace:prompt";

/** Closed union of valid prompt lifecycle statuses. Matches the literal
 *  union in workspace-types.ts:PromptVersion.status verbatim. */
type Status = "draft" | "review" | "production" | "deprecated";

const ws = () => useWorkspaceStore.getState();

function nowIso(): string {
  return new Date().toISOString();
}

/** Compare two semver-ish strings numerically, descending (newest first).
 *  Mirrors compareSemverDesc in prompt-registry-client.tsx so the agent
 *  surface and the UI sort versions the same way (e.g. "1.10.0" beats
 *  "1.9.0", not the other way around as localeCompare would do). */
function compareSemverDesc(a: string, b: string): number {
  const pa = String(a ?? "")
    .split(".")
    .map((x) => parseInt(x, 10) || 0);
  const pb = String(b ?? "")
    .split(".")
    .map((x) => parseInt(x, 10) || 0);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const da = pa[i] ?? 0;
    const db = pb[i] ?? 0;
    if (da !== db) return db - da;
  }
  return 0;
}

/** One name's worth of prompt versions, plus pointers to the production
 *  + latest-draft rows the agent is most likely to want one click away. */
interface PromptGroup {
  name: string;
  versions: PromptVersion[];
  productionVersion: PromptVersion | null;
  latestDraftVersion: PromptVersion | null;
}

interface ListStateResult {
  totalPrompts: number;
  totalVersions: number;
  byStatus: Record<Status, number>;
  groups: PromptGroup[];
}

/** Build the {totalPrompts, totalVersions, byStatus, groups} response.
 *  Kept as a single helper so the browser-path and MCP-path responses
 *  are guaranteed identical — drift would mean an agent gets different
 *  shapes depending on whether it's invoked from chat or over MCP. */
function summarize(items: PromptVersion[]): ListStateResult {
  const byStatus: Record<Status, number> = {
    draft: 0,
    review: 0,
    production: 0,
    deprecated: 0,
  };
  for (const p of items) {
    if (p.status in byStatus) byStatus[p.status] += 1;
  }

  // Bucket by name.
  const byName = new Map<string, PromptVersion[]>();
  for (const p of items) {
    const arr = byName.get(p.name);
    if (arr) arr.push(p);
    else byName.set(p.name, [p]);
  }

  const groups: PromptGroup[] = [];
  // Array.from + forEach instead of `for…of` on a Map iterator — keeps
  // tsconfig.target=ES5/ES2017 builds happy without flipping
  // --downlevelIteration on the whole project.
  Array.from(byName.entries()).forEach(([name, versions]) => {
    const sorted = [...versions].sort((a, b) => compareSemverDesc(a.version, b.version));
    // Production pointer: defensive against multi-production state —
    // pick the most recently publishedAt one as a deterministic
    // tiebreaker. Same logic as get_production_prompt below; kept
    // duplicated rather than DRYed because they have slightly different
    // return shapes.
    const prodCandidates = sorted.filter((p) => p.status === "production");
    const productionVersion =
      prodCandidates.length === 0
        ? null
        : prodCandidates.length === 1
          ? prodCandidates[0]
          : [...prodCandidates].sort((a, b) =>
              String(b.publishedAt ?? "").localeCompare(String(a.publishedAt ?? ""))
            )[0];
    const latestDraftVersion = sorted.find((p) => p.status === "draft") ?? null;
    groups.push({
      name,
      versions: sorted,
      productionVersion,
      latestDraftVersion,
    });
  });

  // Stable name order so consecutive calls return groups in the same
  // sequence — agents that diff list_state responses won't see noise.
  groups.sort((a, b) => a.name.localeCompare(b.name));

  return {
    totalPrompts: byName.size,
    totalVersions: items.length,
    byStatus,
    groups,
  };
}

// ──────── tool.prompt_registry.list_state ────────
// Grouped snapshot + summary stats. The agent's most common opening
// question for a prompt registry is "what's the state of my prompts?"
// — returning groups, byStatus, AND totals in one round-trip avoids a
// follow-up reduce on the agent's end.
registry.register({
  id: "tool.prompt_registry.list_state",
  toolId: "tool.prompt_registry",
  name: "list_state",
  category: "read",
  description:
    "List all prompt versions in the workspace, grouped by name. Returns {totalPrompts (unique names), totalVersions, byStatus: {draft, review, production, deprecated}, groups: [{name, versions[sorted by semver desc], productionVersion?, latestDraftVersion?}]}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().prompts ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<PromptVersion>(ctx.userId, KIND_PROMPT);
    return summarize(items);
  },
});

// ──────── tool.prompt_registry.get_production_prompt ────────
// {name} → the version currently in production for that name, or null.
// Defensive against multi-production state: if more than one row
// ended up tagged production (the in-app UI allowed it before it
// enforced one production version per name),
// the row with the latest publishedAt wins. Returns the full
// PromptVersion so the caller can grab .body directly without a
// follow-up workspace.prompt.get.
registry.register({
  id: "tool.prompt_registry.get_production_prompt",
  toolId: "tool.prompt_registry",
  name: "get_production_prompt",
  category: "read",
  description:
    "Resolve a prompt name to its currently-deployed (status='production') PromptVersion, or null if none. Defensive tiebreaker: if multiple versions are inexplicably tagged production, the row with the latest publishedAt wins.",
  paramsSchema: z.object({
    name: z.string().min(1).max(200).describe("The prompt name (shared across versions)"),
  }),
  handler: async (params) => {
    const items = ws().prompts ?? [];
    const candidates = items.filter((p) => p.name === params.name && p.status === "production");
    return { prompt: pickProduction(candidates) };
  },
  mcpHandler: async (params, ctx) => {
    // No name index on user_entities — pull the whole prompt kind and
    // filter in memory. For realistic registry sizes (<10k versions)
    // this is fine; if it gets pathological we'd want a payload-shaped
    // GIN index, but that's a workspace-wide migration not this tool's
    // problem.
    const all = await serverListEntities<PromptVersion>(ctx.userId, KIND_PROMPT);
    const candidates = all.filter((p) => p.name === params.name && p.status === "production");
    return { prompt: pickProduction(candidates) };
  },
});

/** Pick the single production winner from N candidates. Sole-candidate
 *  fast path skips the publishedAt sort (which would compare two
 *  identical strings against themselves). Null when the list is empty. */
function pickProduction(candidates: PromptVersion[]): PromptVersion | null {
  if (candidates.length === 0) return null;
  if (candidates.length === 1) return candidates[0];
  // publishedAt is ISO-8601, so a lexicographic compare IS a chronological
  // compare. Sort descending — latest first.
  return [...candidates].sort((a, b) =>
    String(b.publishedAt ?? "").localeCompare(String(a.publishedAt ?? ""))
  )[0];
}

// ──────── tool.prompt_registry.promote_to_production ────────
// Set status="production" on the target AND auto-demote any OTHER
// version of the same `name` from production to deprecated, enforcing
// the single-production-per-name invariant. The in-app Publish button
// and status menu apply the same rule (`promote` in
// prompt-registry-client.tsx).
//
// Stamps publishedAt to now if the target doesn't already carry one
// (as the in-app status menu does; the Publish button always restamps).
//
// requiresConfirmation defaults to true for `write` — this is a real
// production cut-over and the agent should pause before executing it.
registry.register({
  id: "tool.prompt_registry.promote_to_production",
  toolId: "tool.prompt_registry",
  name: "promote_to_production",
  category: "write",
  description:
    "Promote a prompt version to status='production'. Auto-demotes any OTHER version of the same name currently in production to 'deprecated' (enforces single-production-per-name invariant). Stamps publishedAt if missing. Returns {promoted: false} when the id is unknown; otherwise {promoted: true, demoted: string[] (ids that were auto-demoted)}.",
  paramsSchema: z.object({
    id: z.string(),
  }),
  handler: async (params) => {
    const all = ws().prompts ?? [];
    const target = all.find((p) => p.id === params.id);
    if (!target) return { promoted: false, demoted: [] as string[] };
    const upsert = useWorkspaceStore.getState().upsertPrompt;
    // Demote any OTHER version of the same name currently in production.
    // Filtering by id !== target.id covers the no-op case where the
    // target is itself already in production (we don't want to demote
    // it then re-promote it — same row, redundant write).
    const toDemote = all.filter(
      (p) => p.name === target.name && p.status === "production" && p.id !== target.id
    );
    for (const d of toDemote) {
      upsert({ ...d, status: "deprecated" });
    }
    upsert({
      ...target,
      status: "production",
      publishedAt: target.publishedAt ?? nowIso(),
    });
    return { promoted: true, demoted: toDemote.map((d) => d.id) };
  },
  mcpHandler: async (params, ctx) => {
    const target = await serverGetEntity<PromptVersion>(ctx.userId, KIND_PROMPT, params.id);
    if (!target) return { promoted: false, demoted: [] as string[] };
    // serverGetEntity fetches one row by id; for the demote step we
    // need ALL rows sharing the same name. user_entities has no
    // payload-field index, so list + filter is the right shape (see
    // the same caveat in get_production_prompt).
    const all = await serverListEntities<PromptVersion>(ctx.userId, KIND_PROMPT);
    const toDemote = all.filter(
      (p) => p.name === target.name && p.status === "production" && p.id !== target.id
    );
    const writes: PromptVersion[] = toDemote.map((d) => ({
      ...d,
      status: "deprecated" as const,
    }));
    writes.push({
      ...target,
      status: "production" as const,
      publishedAt: target.publishedAt ?? nowIso(),
    });
    // Bulk upsert in one round-trip. The browser-path doesn't need this
    // optimisation (it's a local Zustand mutation), but on MCP each
    // serverUpsertEntity is a network hop — promoting a prompt with
    // an existing production peer would otherwise be 2 round-trips.
    await serverBulkUpsertEntities<PromptVersion>(ctx.userId, KIND_PROMPT, writes);
    return { promoted: true, demoted: toDemote.map((d) => d.id) };
  },
});

// ──────── tool.prompt_registry.deprecate ────────
// Set status="deprecated", optionally appending a reason to changeNote.
// Idempotent — calling on an already-deprecated version is a no-op
// (returns {updated: false}) so an LLM-driven "retire all v1.x"
// sweep won't repeatedly write the same row.
//
// requiresConfirmation:false — deprecating is reversible (set the
// status back via workspace.prompt.update) and the natural agent
// phrasing — "deprecate the old version" — would be unbearable to
// confirm one-by-one across a batch.
registry.register({
  id: "tool.prompt_registry.deprecate",
  toolId: "tool.prompt_registry",
  name: "deprecate",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark a prompt version as status='deprecated'. Optionally appends a reason to changeNote. Idempotent — returns {updated: false} when the version is already deprecated OR the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    reason: z
      .string()
      .max(500)
      .optional()
      .describe("Optional human-readable reason; appended to changeNote."),
  }),
  handler: async (params) => {
    const items = ws().prompts ?? [];
    const current = items.find((p) => p.id === params.id);
    if (!current) return { updated: false };
    if (current.status === "deprecated" && !params.reason) {
      // Already deprecated and no new note to record — true no-op.
      return { updated: false };
    }
    const nextNote = appendReason(current.changeNote, params.reason);
    ws().upsertPrompt({ ...current, status: "deprecated", changeNote: nextNote });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<PromptVersion>(ctx.userId, KIND_PROMPT, params.id);
    if (!current) return { updated: false };
    if (current.status === "deprecated" && !params.reason) {
      return { updated: false };
    }
    const nextNote = appendReason(current.changeNote, params.reason);
    await serverUpsertEntity<PromptVersion>(ctx.userId, KIND_PROMPT, {
      ...current,
      status: "deprecated",
      changeNote: nextNote,
    });
    return { updated: true };
  },
});

/** Append a deprecation reason to an existing changeNote in a way that
 *  preserves prior history. No reason → return existing note unchanged
 *  (so the no-op path is byte-identical when reason is omitted). */
function appendReason(
  existing: string | undefined,
  reason: string | undefined
): string | undefined {
  if (!reason) return existing;
  const tag = `[deprecated] ${reason}`;
  if (!existing || existing.trim() === "") return tag;
  return `${existing}\n${tag}`;
}

// ──────── tool.prompt_registry.record_eval ────────
// Set evalScore on a version. The surface is intentionally minimal —
// an LLM-eval agent's typical loop is "run eval → write score back" and
// we don't want it to have to read-merge-write the whole row.
//
// requiresConfirmation:false — overwriting an eval score is
// non-destructive in any load-bearing sense (the previous score is a
// metric, not state the user relies on). Also keeps a 50-prompt eval
// sweep from prompting 50 times.
registry.register({
  id: "tool.prompt_registry.record_eval",
  toolId: "tool.prompt_registry",
  name: "record_eval",
  category: "write",
  requiresConfirmation: false,
  description:
    "Record an evaluation score on a prompt version. Overwrites any prior score. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    evalScore: z
      .number()
      .min(0)
      .max(1)
      .describe("Evaluation score in [0, 1]; conventionally displayed as a percentage in the UI"),
  }),
  handler: async (params) => {
    const items = ws().prompts ?? [];
    const current = items.find((p) => p.id === params.id);
    if (!current) return { updated: false };
    ws().upsertPrompt({ ...current, evalScore: params.evalScore });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<PromptVersion>(ctx.userId, KIND_PROMPT, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<PromptVersion>(ctx.userId, KIND_PROMPT, {
      ...current,
      evalScore: params.evalScore,
    });
    return { updated: true };
  },
});
